// @saas/csv-io — CSV export helpers (E325).
//
// Ported directly (no domain logic to generalize): RFC-4180-ish quoting +
// a UTF-8 BOM so Excel opens the file with the correct encoding. Pure — no db
// import — used by both export and import (import re-parses raw lines, not this
// function, but shares the same escaping contract).

/** Escape a single CSV cell: wrap in quotes (doubling embedded quotes) iff it contains a comma, quote, or newline. */
export function escapeCsvCell(value: unknown): string {
  const s = value === null || value === undefined ? "" : String(value)
  if (/[",\r\n]/.test(s)) {
    return `"${s.replace(/"/g, '""')}"`
  }
  return s
}

/**
 * Compose `header` + `rows` into a CSV string with a UTF-8 BOM (so Excel renders
 * non-ASCII text correctly) and CRLF line endings. Rows may have fewer cells than
 * `header` — missing cells render as empty.
 */
export function toCsv(header: string[], rows: (readonly unknown[])[]): string {
  const lines: string[] = []
  lines.push(header.map(escapeCsvCell).join(","))
  for (const row of rows) {
    lines.push(row.map(escapeCsvCell).join(","))
  }
  return "﻿" + lines.join("\r\n")
}

// @saas/csv-io — generic CSV import: parse + per-row validate + row cap (E325).
//
// Ported from a fork's user-roster CSV importer, generalized off any single record
// shape: the caller supplies a header-name → field-key mapper and a per-row
// validator/coercer (e.g. a Zod `safeParse` call), instead of this module hardcoding
// column names or a Zod schema. Upsert-by-key semantics (insert vs. update, uniqueness
// enforcement) belong to the caller's Server Action — this module only parses and
// validates rows; it never touches the database.
//
// PURE — no db import — independently unit-testable. Tolerant of a UTF-8 BOM, CRLF/LF
// line endings, RFC-4180 quote escaping (`"a,b"`, `""` → `"`), and blank lines (which
// do not consume a row number).

export interface RowError {
  /** 1-based data-row number (header excluded; blank lines don't consume a number). */
  row: number
  reason: string
}

export type ParseRowResult<T> = { success: true; data: T } | { success: false; reason: string }

export interface ParseCsvOptions<T> {
  /** Maps one normalized header cell to an internal field key, or `null` to ignore the column. */
  headerKey: (rawHeader: string) => string | null
  /** Internal field keys that MUST be present in the header — a missing one is a whole-file error. */
  requiredKeys: readonly string[]
  /**
   * Validate + coerce one row's `{ fieldKey: rawCellValue }` map (all values are
   * trimmed strings). Return `{ success: false, reason }` to record a per-row error
   * without aborting the rest of the parse — e.g. wrap a Zod `safeParse`.
   */
  parseRow: (cells: Record<string, string>, rowNumber: number) => ParseRowResult<T>
  /** Max data rows accepted before the parse stops (protects against pathological uploads). Default 1000. */
  maxRows?: number
}

export interface ParseCsvResult<T> {
  rows: T[]
  errors: RowError[]
  /** True when `maxRows` was hit — rows beyond the cap were NOT parsed (not counted as errors). */
  truncated: boolean
}

/** Split one CSV line into raw cells (RFC-4180: quote-wrapped fields, `""` escapes a literal quote). */
function splitCsvLine(line: string): string[] {
  const out: string[] = []
  let cur = ""
  let inQuotes = false
  for (let i = 0; i < line.length; i++) {
    const ch = line[i]
    if (inQuotes) {
      if (ch === '"') {
        if (line[i + 1] === '"') {
          cur += '"'
          i++
        } else {
          inQuotes = false
        }
      } else {
        cur += ch
      }
    } else if (ch === '"') {
      inQuotes = true
    } else if (ch === ",") {
      out.push(cur)
      cur = ""
    } else {
      cur += ch
    }
  }
  out.push(cur)
  return out.map((c) => c.trim())
}

/**
 * Parse `text` into validated rows + per-row errors, per `options`.
 *
 * - The first non-blank line is the header; every other non-blank line is a data row.
 * - A blank line is skipped and does not consume a row number.
 * - Missing a `requiredKeys` column, or an entirely empty file, short-circuits with a
 *   single `row: 0` error and no parsed rows.
 * - Per-row validation failures are collected in `errors` — the parse does not abort.
 */
export function parseCsv<T>(text: string, options: ParseCsvOptions<T>): ParseCsvResult<T> {
  const maxRows = options.maxRows ?? 1000
  const rows: T[] = []
  const errors: RowError[] = []

  // Strip a leading UTF-8 BOM and normalize CRLF/CR to LF.
  const clean = text.replace(/^﻿/, "").replace(/\r\n?/g, "\n")
  const rawLines = clean.split("\n")

  let headerIdx = -1
  for (let i = 0; i < rawLines.length; i++) {
    if (rawLines[i].trim() !== "") {
      headerIdx = i
      break
    }
  }
  if (headerIdx === -1) {
    return { rows, errors: [{ row: 0, reason: "CSV content is empty" }], truncated: false }
  }

  const headerCells = splitCsvLine(rawLines[headerIdx])
  const colIndex: Record<string, number> = {}
  headerCells.forEach((cell, idx) => {
    const key = options.headerKey(cell)
    if (key && colIndex[key] === undefined) colIndex[key] = idx
  })

  for (const key of options.requiredKeys) {
    if (colIndex[key] === undefined) {
      return { rows, errors: [{ row: 0, reason: `Missing required column: ${key}` }], truncated: false }
    }
  }

  let dataRow = 0
  let truncated = false
  for (let i = headerIdx + 1; i < rawLines.length; i++) {
    if (rawLines[i].trim() === "") continue // blank line — doesn't consume a row number
    if (dataRow >= maxRows) {
      truncated = true
      break
    }
    dataRow++

    const cells = splitCsvLine(rawLines[i])
    const record: Record<string, string> = {}
    for (const [key, idx] of Object.entries(colIndex)) {
      record[key] = (cells[idx] ?? "").trim()
    }

    const parsed = options.parseRow(record, dataRow)
    if (!parsed.success) {
      errors.push({ row: dataRow, reason: parsed.reason })
      continue
    }
    rows.push(parsed.data)
  }

  return { rows, errors, truncated }
}

"use client"

// @saas/csv-io — reference bulk-import dialog (E325).
//
// A thin shadcn Dialog wrapper: pick a file, hand its text to the caller's `onImport`
// (which should call `parseCsv()` from `@/lib/csv-io/import` plus the caller's own
// upsert-by-key Server Action), and render the resulting per-row error list. This
// component holds NO parsing/db logic itself — it is a starting point to copy/adapt
// per module, not a one-size-fits-all import UI.
import { useState, useTransition } from "react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import type { RowError } from "@/lib/csv-io/import"

export interface CsvImportResult {
  imported: number
  errors: RowError[]
}

export interface CsvImportDialogProps {
  title: string
  description?: string
  triggerLabel?: string
  /** Read the picked file's text, parse + upsert it, and report a result summary. */
  onImport: (text: string) => Promise<CsvImportResult>
  /** Called after an import with zero row errors (e.g. `router.refresh()`). */
  onDone?: () => void
}

export function CsvImportDialog({
  title,
  description,
  triggerLabel = "Import CSV",
  onImport,
  onDone,
}: CsvImportDialogProps) {
  const [open, setOpen] = useState(false)
  const [file, setFile] = useState<File | null>(null)
  const [result, setResult] = useState<CsvImportResult | null>(null)
  const [isPending, startTransition] = useTransition()

  function handleOpenChange(next: boolean) {
    setOpen(next)
    if (!next) {
      setFile(null)
      setResult(null)
    }
  }

  function handleImport() {
    if (!file) return
    startTransition(async () => {
      const text = await file.text()
      const next = await onImport(text)
      setResult(next)
      if (next.errors.length === 0) {
        onDone?.()
      }
    })
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogTrigger asChild>
        <Button variant="outline">{triggerLabel}</Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          {description ? <DialogDescription>{description}</DialogDescription> : null}
        </DialogHeader>

        <Input
          type="file"
          accept=".csv,text/csv"
          onChange={(e) => setFile(e.target.files?.[0] ?? null)}
        />

        {result ? (
          <div className="text-sm">
            <p>{result.imported} row(s) imported.</p>
            {result.errors.length > 0 ? (
              <ul className="mt-2 max-h-40 list-disc space-y-1 overflow-y-auto pl-4 text-destructive">
                {result.errors.map((e) => (
                  <li key={e.row}>
                    Row {e.row}: {e.reason}
                  </li>
                ))}
              </ul>
            ) : null}
          </div>
        ) : null}

        <DialogFooter>
          <Button onClick={handleImport} disabled={!file || isPending}>
            {isPending ? "Importing…" : "Import"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

{
  "$schema": "../schema/module.manifest.schema.json",
  "id": "csv-io",
  "version": "1.0.0",
  "title": "CSV Import/Export",
  "summary": "toCsv/escapeCsvCell export helpers plus a generic CSV import parser (upsert-by-key friendly, per-row errors, row cap) and a reference bulk-import dialog. Generalized to any keyed record shape — not tied to a specific table.",
  "registryDependencies": ["dialog", "button", "input"],
  "npmDependencies": {},
  "npmDevDependencies": {},
  "envVars": [],
  "dbTables": [],
  "db": {},
  "routes": [],
  "serverActions": [],
  "postInstall": [
    {
      "step": 1,
      "action": "manual",
      "description": "For export: call toCsv(header, rows) from lib/csv-io/csv.ts wherever you build a CSV download response (e.g. a route handler returning Content-Type: text/csv)."
    },
    {
      "step": 2,
      "action": "manual",
      "description": "For import: call parseCsv(text, { headerKey, requiredKeys, parseRow }) from lib/csv-io/import.ts inside a Server Action. Supply headerKey to map your CSV's column names to field keys, and parseRow to validate/coerce each row (e.g. wrap a Zod schema's safeParse). The action then does the upsert-by-key against your table — this module does not touch the database."
    },
    {
      "step": 3,
      "action": "manual",
      "description": "Wire components/csv-import-dialog.tsx's onImport prop to your Server Action; it returns { imported, errors } which the dialog renders as a per-row error list. Adapt or replace the component per your domain — it is a reference starting point, not a drop-in for every table."
    },
    {
      "step": 4,
      "action": "command",
      "description": "Run the module's unit tests plus a full verify.",
      "command": "pnpm test && pnpm typecheck && pnpm lint"
    }
  ],
  "docs": "/docs/modules/csv-io",
  "files": [
    {
      "path": "registry/csv-io/lib/csv-io/csv.ts",
      "type": "registry:lib",
      "target": "lib/csv-io/csv.ts"
    },
    {
      "path": "registry/csv-io/lib/csv-io/import.ts",
      "type": "registry:lib",
      "target": "lib/csv-io/import.ts"
    },
    {
      "path": "registry/csv-io/components/csv-import-dialog.tsx",
      "type": "registry:component",
      "target": "components/csv-import-dialog.tsx"
    },
    {
      "path": "registry/csv-io/module.manifest.json",
      "type": "registry:file",
      "target": "registry/csv-io/module.manifest.json"
    }
  ]
}
